        let overview_raw = inference_llm::infer(system, &prompt, "digest");

        // ensures len(overview) <= 600 — enforced here, not trusted from the model.
        let overview = clamp_chars(&overview_raw, MAX_OVERVIEW);

        // ensures len(date) == 10 — carried from the input, which `requires`
        // guarantees is already length 10.
        Digest {
            date: info.date,
            overview,
            entries: selected.entries,
            considered: selected.considered,
        }
    }
}

